// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, uint8 dataLen) public {
        vm.assume(amount <= address(c).balance);
        vm.assume(dataLen < 64);
        bytes memory data = new bytes(dataLen);
        for (uint8 i = 0; i < dataLen; i++) {
            data[i] = bytes1(uint8(0xff));
        }
        Reverter reverter = new Reverter();
        uint balanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();
        bool success = true;
        try c.sendMoney(address(reverter), amount, data) {
        } catch {
            success = false;
        }
        uint balanceAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();
        if (success) {
            assertTrue(depositsAfter == depositsBefore + 1);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}
contract Reverter {
    fallback() external payable {
        revert();
    }
}
